//! Real-media archive fixtures; committed generated bytes, no public peers.
use super::*;
use crate::{
    credentials::{KeySpec, Quotas},
    protocol::CreateSession,
};
use librqbit::{
    create_torrent, AddTorrent, AddTorrentOptions, CreateTorrentOptions, Session, SessionOptions,
};
use std::{
    path::{Path, PathBuf},
    time::Duration,
};

fn assets() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../engine/assets/rar-media")
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
#[ignore = "requires real FFmpeg/ffprobe; local stored multi-volume torrent fixture"]
async fn real_stored_multivolume_torrent_archive_hls_shares_and_seeks() {
    archive_fixture(true).await;
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
#[ignore = "requires real FFmpeg/ffprobe; local compressed torrent fixture"]
async fn real_compressed_torrent_archive_hls_extracts_before_playback() {
    archive_fixture(false).await;
}

async fn archive_fixture(stored: bool) {
    let ffmpeg = std::env::var("PLAYBACK_TEST_FFMPEG").expect("FFmpeg fixture path");
    let ffprobe = std::env::var("PLAYBACK_TEST_FFPROBE").expect("ffprobe fixture path");
    let root = tempfile::tempdir().unwrap();
    let seed_dir = root.path().join("seed");
    std::fs::create_dir(&seed_dir).unwrap();
    if stored {
        for index in 1..=4 {
            let name = format!("clip.part{index}.rar");
            std::fs::copy(assets().join("stored").join(&name), seed_dir.join(name)).unwrap();
        }
    } else {
        std::fs::copy(assets().join("compressed.rar"), seed_dir.join("clip.rar")).unwrap();
    }
    let torrent = create_torrent(
        &seed_dir,
        CreateTorrentOptions {
            piece_length: Some(16 * 1024),
            ..Default::default()
        },
    )
    .await
    .unwrap();
    let metainfo = torrent.as_bytes().unwrap();
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let peer_port = listener.local_addr().unwrap().port();
    drop(listener);
    let seed = Session::new_with_opts(
        seed_dir.clone(),
        SessionOptions {
            disable_dht: true,
            disable_dht_persistence: true,
            listen_port_range: Some(peer_port..peer_port + 1),
            ..Default::default()
        },
    )
    .await
    .unwrap();
    let seeded = seed
        .add_torrent(
            AddTorrent::from_bytes(metainfo.clone()),
            Some(AddTorrentOptions {
                output_folder: Some(seed_dir.to_str().unwrap().into()),
                overwrite: true,
                ..Default::default()
            }),
        )
        .await
        .unwrap()
        .into_handle()
        .unwrap();
    seeded.wait_until_initialized().await.unwrap();
    let route = axum::Router::new().route(
        "/archive.torrent",
        axum::routing::get(move || {
            let bytes = metainfo.clone();
            async move { bytes }
        }),
    );
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let source_url = format!("http://{}/archive.torrent", listener.local_addr().unwrap());
    let http = tokio::spawn(async move { axum::serve(listener, route).await.unwrap() });
    let engine = PlaybackManager::new(playback_engine::Config {
        ffmpeg: ffmpeg.clone().into(),
        ffprobe: ffprobe.into(),
        root: root.path().join("media"),
        max_sessions: 4,
        ttl: Duration::from_secs(120),
    });
    let credentials = Arc::new(
        Credentials::from_connection(
            rusqlite::Connection::open_in_memory().unwrap(),
            tests::BOOTSTRAP,
        )
        .unwrap(),
    );
    let key = credentials
        .issue(
            tests::BOOTSTRAP,
            KeySpec {
                label: "Archive fixture".into(),
                namespaces: vec!["fixture".into()],
                scopes: vec![
                    Scope::Create,
                    Scope::Read,
                    Scope::Renew,
                    Scope::Release,
                    Scope::Capabilities,
                ],
                quotas: Quotas {
                    inputs: 4,
                    outputs: 4,
                    viewers: 8,
                },
                expires_at: None,
            },
            0,
        )
        .unwrap();
    let principal = credentials.authenticate(&key.secret, 0).unwrap();
    let cache = root.path().join("torrent-cache");
    let workers = Workers::new_with_torrent(
        engine,
        credentials,
        NetworkPolicy::loopback_fixture(),
        playback_engine::TorrentConfig {
            enabled: true,
            cache_dir: cache.clone(),
            enable_dht: false,
            initial_peers: vec![format!("127.0.0.1:{peer_port}").parse().unwrap()],
            idle_timeout: Duration::ZERO,
            ..Default::default()
        },
    )
    .await
    .unwrap();
    let mut request:CreateSession=serde_json::from_value(serde_json::json!({"namespace":"fixture","input":{"url":source_url,"live":false},"output":{"protocol":"hls","conversion":"video","video_codecs":["h264"],"audio_codecs":["aac"],"max_width":320,"max_height":180}})).unwrap();
    let first = workers
        .create(&principal, &request, "first", 0)
        .await
        .unwrap();
    let second = workers
        .create(&principal, &request, "second", 1)
        .await
        .unwrap();
    assert_eq!(
        first.job_id, second.job_id,
        "archive extraction and normalized output must be shared"
    );
    assert_eq!(workers.input_file(&first).unwrap().name, "clip.mp4");
    let path = output_path(&workers, &first, root.path());
    decode_output(&ffmpeg, &path, root.path(), "first").await;
    let spools = spool_files(&cache);
    if stored {
        assert!(
            spools.is_empty(),
            "stored ranges must not create a decoded spool"
        );
    } else {
        assert_eq!(spools.len(), 1, "compressed archive must be extracted once");
        assert_eq!(
            std::fs::read(&spools[0]).unwrap(),
            std::fs::read(assets().join("clip.mp4")).unwrap(),
            "complete checksum-verified spool must match original media"
        );
    }
    request.position_seconds = 3.0;
    let sought = workers
        .create(&principal, &request, "sought", 2)
        .await
        .unwrap();
    assert_ne!(first.job_id, sought.job_id);
    let sought_path = output_path(&workers, &sought, root.path());
    decode_output(&ffmpeg, &sought_path, root.path(), "sought").await;
    assert_seek(&ffmpeg, &sought_path, root.path()).await;
    if !stored {
        assert_eq!(
            spool_files(&cache).len(),
            1,
            "different VOD seek must reuse complete archive spool"
        );
    }
    for viewer in [&first, &second, &sought] {
        workers
            .sessions
            .lock()
            .unwrap()
            .release(&principal, &viewer.id, 4)
            .unwrap();
    }
    workers.reap(40).await.unwrap();
    assert_eq!(workers.available(&principal, 40).unwrap().inputs, 4);
    assert_eq!(workers.engine.available_output_slots(), 4);
    assert!(workers.input_sources.lock().unwrap().is_empty());
    assert!(spool_files(&cache).is_empty());
    workers.shutdown().await;
    http.abort();
    seed.cancellation_token().cancel();
    println!("Archive fixture: stored={stored}; two viewers shared output; 3s seek decoded; last release reclaimed torrent and spool.");
}
fn output_path(workers: &Workers, viewer: &Viewer, root: &Path) -> PathBuf {
    root.join("media").join(
        &workers
            .active
            .lock()
            .unwrap()
            .get(&viewer.job_id)
            .unwrap()
            .id,
    )
}
fn spool_files(cache: &Path) -> Vec<PathBuf> {
    std::fs::read_dir(cache)
        .into_iter()
        .flatten()
        .filter_map(Result::ok)
        .filter(|entry| entry.path().is_dir())
        .flat_map(|entry| {
            std::fs::read_dir(entry.path())
                .into_iter()
                .flatten()
                .filter_map(Result::ok)
                .map(|entry| entry.path())
                .collect::<Vec<_>>()
        })
        .filter(|path| {
            path.file_name()
                .is_some_and(|name| name.to_string_lossy().starts_with("rar-"))
        })
        .collect()
}
fn playlist(media: &Path) -> PathBuf {
    std::fs::read_dir(media)
        .unwrap()
        .filter_map(Result::ok)
        .map(|e| e.path())
        .find(|p| p.extension().is_some_and(|e| e == "m3u8"))
        .expect("output playlist")
}
async fn decode_output(ffmpeg: &str, media: &Path, root: &Path, label: &str) {
    let output = root.join(format!("{label}.md5"));
    let decoded = tokio::process::Command::new(ffmpeg)
        .args([
            "-v",
            "error",
            "-nostdin",
            "-protocol_whitelist",
            "file,crypto,data",
            "-i",
        ])
        .arg(playlist(media))
        .args(["-frames:v", "8", "-f", "framemd5"])
        .arg(&output)
        .output()
        .await
        .unwrap();
    assert!(
        decoded.status.success(),
        "managed archive HLS output must decode"
    );
    assert_eq!(
        std::fs::read_to_string(output)
            .unwrap()
            .lines()
            .filter(|line| line.starts_with("0,"))
            .count(),
        8
    );
}
async fn assert_seek(ffmpeg: &str, media: &Path, root: &Path) {
    let playlist = playlist(media);
    let movie = assets().join("clip.mp4");
    for (name, path, seconds) in [
        ("observed", playlist.as_path(), 0),
        ("expected", movie.as_path(), 3),
        ("zero", movie.as_path(), 0),
    ] {
        let mut command = tokio::process::Command::new(ffmpeg);
        command.args(["-v", "error", "-nostdin"]);
        if seconds > 0 {
            command.args(["-ss", "3"]);
        }
        let result = command
            .arg("-i")
            .arg(path)
            .args(["-frames:v", "1", "-pix_fmt", "rgb24", "-f", "rawvideo"])
            .arg(root.join(name))
            .output()
            .await
            .unwrap();
        assert!(result.status.success());
    }
    let observed = std::fs::read(root.join("observed")).unwrap();
    let expected = std::fs::read(root.join("expected")).unwrap();
    let zero = std::fs::read(root.join("zero")).unwrap();
    assert_eq!(observed.len(), 160 * 90 * 3);
    assert_eq!(observed.len(), expected.len());
    let mse = |reference: &[u8]| {
        observed
            .iter()
            .zip(reference)
            .map(|(a, b)| {
                let delta = f64::from(*a) - f64::from(*b);
                delta * delta
            })
            .sum::<f64>()
            / observed.len() as f64
    };
    assert!(
        mse(&expected) < 100.0,
        "requested seek must match source frame; requested={} zero={}",
        mse(&expected),
        mse(&zero)
    );
    assert!(
        mse(&expected) < mse(&zero) * 0.1,
        "seek must not restart at zero"
    );
}

#[test]
#[ignore = "requires isolated container with dedicated 2 MiB archive-cache tmpfs"]
fn real_archive_spool_kernel_enospc_is_processing_error_and_removes_partial_output() {
    use std::io::Write;
    let cache = PathBuf::from(
        std::env::var("PLAYBACK_TEST_ARCHIVE_CACHE").expect("bounded archive cache fixture"),
    );
    assert_eq!(cache, Path::new("/var/lib/playback-gateway/archive-cache"));
    let fill = cache.join("capacity-fixture.bin");
    let mut file = std::fs::File::create(&fill).unwrap();
    let block = [0u8; 4096];
    let mut written = 0;
    loop {
        match file.write_all(&block) {
            Ok(()) => {
                written += block.len();
                assert!(written <= 2 * 1024 * 1024);
            }
            Err(error) => {
                assert_eq!(error.raw_os_error(), Some(libc::ENOSPC));
                break;
            }
        }
    }
    assert_eq!(
        written,
        2 * 1024 * 1024,
        "dedicated mount must have the exact filesystem bound"
    );
    let volume = playback_engine::rar::local_volume(&assets().join("compressed.rar")).unwrap();
    let result = playback_engine::rar::RarMedia::open(vec![volume], &cache, 1024 * 1024);
    assert_eq!(
        result.err(),
        Some("processing_failed"),
        "kernel ENOSPC must be a processing error, never readable partial media/clean EOF"
    );
    assert_eq!(
        std::fs::read_dir(&cache).unwrap().count(),
        1,
        "failed extraction must remove its partial spool"
    );
    drop(file);
    std::fs::remove_file(fill).unwrap();
    let volume = playback_engine::rar::local_volume(&assets().join("compressed.rar")).unwrap();
    let recovered =
        playback_engine::rar::RarMedia::open(vec![volume], &cache, 1024 * 1024).unwrap();
    assert_eq!(
        recovered.read_range(0, 16).unwrap(),
        std::fs::read(assets().join("clip.mp4")).unwrap()[..16]
    );
    drop(recovered);
    assert_eq!(std::fs::read_dir(cache).unwrap().count(), 0);
    println!("Archive cache kernel ENOSPC at {written} bytes: processing_failed, partial removed, restart succeeded.");
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn cancelled_archive_reader_keeps_key_quota_until_actual_read_completion() {
    use std::sync::atomic::{AtomicBool, Ordering};
    let (root, workers, principal) = tests::fixture(false).await;
    let blocked = Arc::new(AtomicBool::new(false));
    let started = Arc::new(tokio::sync::Notify::new());
    let release = Arc::new(tokio::sync::Notify::new());
    let route = axum::Router::new().route(
        "/clip.rar",
        axum::routing::get({
            let blocked = blocked.clone();
            let started = started.clone();
            let release = release.clone();
            move |headers: axum::http::HeaderMap| {
                let blocked = blocked.clone();
                let started = started.clone();
                let release = release.clone();
                async move {
                    let bytes = include_bytes!(concat!(
                        env!("CARGO_MANIFEST_DIR"),
                        "/../engine/assets/rar/stored.rar"
                    ));
                    let range = headers
                        .get("Range")
                        .unwrap()
                        .to_str()
                        .unwrap()
                        .strip_prefix("bytes=")
                        .unwrap();
                    let (from, to) = range.split_once('-').unwrap();
                    let (from, to) = (from.parse::<usize>().unwrap(), to.parse::<usize>().unwrap());
                    if blocked.load(Ordering::Acquire) {
                        started.notify_one();
                        release.notified().await;
                    }
                    axum::http::Response::builder()
                        .status(206)
                        .header(
                            "Content-Range",
                            format!("bytes {from}-{to}/{}", bytes.len()),
                        )
                        .header("Content-Length", to - from + 1)
                        .body(axum::body::Body::from(bytes[from..=to].to_vec()))
                        .unwrap()
                }
            }
        }),
    );
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let http = tokio::spawn(async move { axum::serve(listener, route).await.unwrap() });
    // The source resolver uses a fixture-only loopback egress policy.
    let proxy = EgressProxy::start(NetworkPolicy::loopback_fixture())
        .await
        .unwrap();
    // The source resolver owns a client using this fixture-only proxy.
    let mut workers = Arc::try_unwrap(workers).ok().unwrap();
    workers.sources = Arc::new(
        Sources::new(
            playback_engine::TorrentConfig {
                enabled: true,
                cache_dir: root.path().join("archive-cache"),
                enable_dht: false,
                ..Default::default()
            },
            &proxy.url(),
        )
        .unwrap(),
    );
    let workers = Arc::new(workers);
    let mut request = tests::request(640);
    request.input.url = format!("http://{address}/clip.rar");
    request.input.live = false;
    let viewer = workers
        .create(&principal, &request, "archive-reader", 0)
        .await
        .unwrap();
    let url = workers
        .input_sources
        .lock()
        .unwrap()
        .get(&viewer.job_id)
        .unwrap()
        .url
        .clone();
    blocked.store(true, Ordering::Release);
    let reading = tokio::spawn(async move {
        reqwest::Client::builder()
            .no_proxy()
            .build()
            .unwrap()
            .get(url)
            .header("Range", "bytes=10-17")
            .send()
            .await
            .unwrap()
            .bytes()
            .await
    });
    tokio::time::timeout(Duration::from_secs(2), started.notified())
        .await
        .unwrap();
    workers
        .sessions
        .lock()
        .unwrap()
        .release(&principal, &viewer.id, 1)
        .unwrap();
    let cleanup = tokio::spawn({
        let workers = workers.clone();
        async move { workers.reap(40).await }
    });
    tokio::time::sleep(Duration::from_millis(60)).await;
    assert!(
        !cleanup.is_finished(),
        "last source quota must remain held while its blocking reader waits upstream"
    );
    assert_eq!(workers.available(&principal, 40).unwrap().inputs, 0);
    assert_eq!(
        tokio::time::timeout(Duration::from_secs(6), cleanup)
            .await
            .unwrap()
            .unwrap(),
        Err("cleanup_pending"),
        "bounded reaper waits must leave the stopping reservation for the next poll"
    );
    assert_eq!(workers.available(&principal, 40).unwrap().inputs, 0);
    reading.abort();
    let _ = reading.await;
    release.notify_one();
    tokio::time::timeout(Duration::from_secs(2), workers.reap(41))
        .await
        .unwrap()
        .unwrap();
    assert_eq!(workers.available(&principal, 40).unwrap().inputs, 1);
    assert!(workers.input_sources.lock().unwrap().is_empty());
    workers.shutdown().await;
    http.abort();
}
